INSERT OR REPLACE INTO products (id, source, source_product_id, name, slug, category, problem_tags, solution_summary, tradeoffs, price_min, price_max, currency, rating, sales_count, image_url, destination_url, affiliate_url, source_updated_at, published_at, status, quality_score, created_at, updated_at) VALUES ('prd-okira-troli-4s', 'shopee_affiliate_feed', '55667756643', 'Rak Troli Dapur & Kamar Mandi 4 Susun Serbaguna Beroda Okira', 'rak-troli-dapur-kamar-mandi-4-susun-serbaguna-beroda-okira-prd-okira-troli-4s', 'kamar-kos', '["botol bumbu dapur dan sabun mandi berantakan","celah sempit samping kulkas tidak termanfaatkan","lantai bawah rak susah dibersihkan karena rak permanen","rak penyimpanan menampung air genangan dan berdebu"]', 'Rak penyimpanan serbaguna 4 susun dengan 4 roda putar 360 derajat dan dasar keranjang berongga anti-genangan untuk merapikan celah sempit di dapur, kamar mandi, atau samping meja.', 'Terbuat dari plastik PP tebal; ideal untuk barang berbobot ringan hingga menengah seperti bumbu, botol perlengkapan mandi, dan skincare (hindari beban berlebih seperti galon air).', 12900, 25000, 'IDR', 4.8, 10000, 'https://images.unsplash.com/photo-1595428774223-ef52624120d2?auto=format&fit=crop&w=800&q=80', 'https://shopee.co.id/product/example/55667756643', 'https://s.shopee.co.id/W7ygZkZ6E', '2026-11-05T12:48:54Z', '2026-11-05T13:00:00Z', 'published', 95, '2026-11-05T12:48:54Z', '2026-11-05T06:53:54.817Z');
